#include "stm32g4xx.h"

void tim1_pa8_pwm_init(void) {
    /* 1. Enable GPIOA and TIM1 peripheral clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 as alternate function AF6 (TIM1_CH1) */
    GPIOA->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos); /* AF mode (10) */

    GPIOA->AFR[1] &= ~(0xFU << GPIO_AFRH_AFSEL8_Pos);
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos); /* AF6 */

    /* 3. Configure TIM1 time base: 170 MHz / (0 + 1) / (8499 + 1) = 20 kHz */
    TIM1->PSC = 0U;
    TIM1->ARR = 8499U;

    /* 4. Configure Channel 1: PWM mode 1, preload enable, 25% duty cycle */
    TIM1->CCR1 = 2125U; /* 2125 / 8500 = 25% */
    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE; /* PWM mode 1 (0110), preload enable */

    /* 5. Enable Channel 1 output */
    TIM1->CCER |= TIM_CCER_CC1E;

    /* 6. Enable Main Output (MOE bit in BDTR, required for advanced timer TIM1) */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 7. Enable counter and auto-reload preload */
    TIM1->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;
}

